<?php
declare(strict_types=1);require dirname(__DIR__,2).'/bootstrap.php';use App\Core\Auth;use App\Core\Database;Auth::requireAdmin();$pdo=Database::connection();$events=$pdo->query("SELECT DISTINCT e.id,e.name,e.event_date FROM bdc_test_events e JOIN bdc_test_scoring_rounds r ON r.event_id=e.id ORDER BY e.event_date DESC,e.name")->fetchAll();$rounds=$pdo->query("SELECT id,event_id,division,round_type,status FROM bdc_test_scoring_rounds ORDER BY event_id,division,FIELD(round_type,'heats','semifinal','final'),id")->fetchAll();?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Test Live Screen Projector</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><style>body{background:#f4f6f9}.workspace{border-radius:16px}.round-chip{border:1px solid #dee2e6;border-radius:10px;padding:10px 14px;background:#fff}.round-chip.active{border-color:#ffc107;background:#fff8dc}.control-frame{width:100%;border:0;min-height:720px}</style></head><body><nav class="navbar navbar-dark bg-dark"><div class="container-fluid"><a class="navbar-brand" href="../scoring-tests/select-mode.php">Scoring Tests</a><a class="btn btn-light btn-sm" href="../">Dashboard</a></div></nav><main class="container py-4"><div class="alert alert-warning fw-bold">TEST MODE · Projection data comes only from Scoring Tests.</div><h1 class="h2">Test Live Screen Projector</h1><p class="text-muted mb-4">Select Event → Category → Round. Test projector controls open below on this same page.</p><div class="card workspace shadow-sm mb-4"><div class="card-body"><div class="row g-3"><div class="col-md-5"><label class="form-label fw-bold">Event</label><select id="event" class="form-select"><option value="">Select event...</option><?php foreach($events as $e):?><option value="<?=(int)$e['id']?>"><?=e($e['name'])?><?=!empty($e['event_date'])?' · '.e($e['event_date']):''?></option><?php endforeach;?></select></div><div class="col-md-4"><label class="form-label fw-bold">Category / Division</label><select id="division" class="form-select" disabled><option value="">Select category...</option></select></div><div class="col-md-3"><label class="form-label fw-bold">Round</label><select id="round" class="form-select" disabled><option value="">Select round...</option></select></div></div></div></div><section id="selected" class="d-none"><div class="small text-muted">AVAILABLE ROUNDS</div><div id="roundsBar" class="d-flex flex-wrap gap-2 my-2"></div><iframe id="controlFrame" class="control-frame" title="Test Live Screen Control"></iframe></section></main><script>const rounds=<?=json_encode($rounds,JSON_UNESCAPED_SLASHES)?>,event=document.querySelector('#event'),division=document.querySelector('#division'),round=document.querySelector('#round'),selected=document.querySelector('#selected'),frame=document.querySelector('#controlFrame'),bar=document.querySelector('#roundsBar'),label=s=>String(s).replaceAll('_',' ').replace(/\b\w/g,c=>c.toUpperCase());event.onchange=()=>{const id=Number(event.value),v=[...new Set(rounds.filter(r=>Number(r.event_id)===id).map(r=>r.division))];division.innerHTML='<option value="">Select category...</option>'+v.map(x=>`<option value="${x}">${label(x)}</option>`).join('');division.disabled=!id;round.disabled=true;selected.classList.add('d-none')};division.onchange=()=>{const v=rounds.filter(r=>Number(r.event_id)===Number(event.value)&&r.division===division.value);round.innerHTML='<option value="">Select round...</option>'+v.map(x=>`<option value="${x.id}">${label(x.round_type)}</option>`).join('');round.disabled=!division.value;bar.innerHTML=v.map(x=>`<button class="round-chip" type="button" data-id="${x.id}">${label(x.round_type)}</button>`).join('');bar.querySelectorAll('button').forEach(b=>b.onclick=()=>{round.value=b.dataset.id;show()});selected.classList.add('d-none')};function show(){const r=rounds.find(x=>Number(x.id)===Number(round.value));if(!r)return;bar.querySelectorAll('button').forEach(b=>b.classList.toggle('active',Number(b.dataset.id)===Number(r.id)));frame.src='test-control.php?round_id='+r.id;selected.classList.remove('d-none')}round.onchange=show;</script></body></html>